mapper.select:
SELECT t1.*, (t1.pledge_proportion * t1.mortgage_amount_total) pledge_amount, (t1.mortgage_amount_total - nvl(t1.release_amount, t1.mortgage_amount_total)) release_amt FROM (SELECT t.project_id, i.lease_item_id, i.lease_item_code, i.full_name, t.hd_id, (SELECT v.MEANING FROM sys_code_value_b_v v WHERE v.code = 'HLS.COLLATERAL_TYPE' AND v.code_value = i.lease_item_type) lease_item_type_n, (SELECT v.MEANING FROM sys_code_value_b_v v WHERE v.code = (CASE WHEN i.lease_item_type = 'MORTGAGE' THEN 'HLS.MORTGAGE_TYPE' ELSE 'HLS.PLEDGE_TYPE' END) AND v.code_value = i.pattern) pattern_n, (SELECT meaning FROM sys_code_value_b_v WHERE code = 'PLEDGE_STATE' AND code_value = i.pledge_state) pledge_state_n, i.mortgage_date_to, nvl(t.pledge_proportion, 0) pledge_proportion, nvl((SELECT SUM(nvl(d.mortgage_pledge_amount, 0)) FROM hls_lease_item_detail d WHERE d.lease_item_id = i.lease_item_id), 0) mortgage_amount_total, (SELECT SUM(nvl(ln.release_amount, 0)) FROM hls_duration_ln ln, hls_lease_item_detail d WHERE ln.source_type = 'RELEASE' AND ln.hd_id = #{hdId} AND ln.lease_item_detail_id = d.lease_item_detail_id AND d.lease_item_id = i.lease_item_id) release_amount FROM hls_duration_item t, hls_lease_item i WHERE t.source_type = 'PLEDGOR_MORTGAGOR' AND t.lease_item_id = i.lease_item_id) t1
t1.hd_id = #{hdId}
order by t1.lease_item_code

SELECT t1.*, (t1.net_asset_value_total_now - nvl(t1.release_amount, t1.net_asset_value_total_now)) release_amt FROM (SELECT t.project_id, i.lease_item_id, i.lease_item_code, i.full_name, t.hd_id, (SELECT hbt.description FROM hls_business_type hbt WHERE hbt.document_category = 'ASSET_TYPES' AND hbt.business_type = i.asset_types) asset_types_n, (SELECT hdt.description FROM hls_document_type hdt WHERE hdt.document_category = 'ASSET_TYPES' AND hdt.business_type = i.asset_types AND hdt.document_type = i.asset_types_sub) asset_types_sub_n, (SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = i.currency) currency_n, (SELECT nvl(SUM(hlid.net_asset_value), 0) FROM hls_lease_item_detail hlid WHERE hlid.lease_item_id = i.lease_item_id) net_asset_value_total, 0 net_asset_value_total_now, (SELECT SUM(nvl(ln.release_amount, 0)) FROM hls_duration_ln ln, hls_lease_item_detail d WHERE ln.source_type = 'REPURCHASE' AND ln.hd_id = #{hdId} AND ln.lease_item_detail_id = d.lease_item_detail_id AND d.lease_item_id = i.lease_item_id) release_amount FROM hls_duration_item t, hls_lease_item i WHERE t.source_type = 'LEASE_ITEM' AND t.lease_item_id = i.lease_item_id) t1
t1.hd_id = #{hdId}
order by t1.lease_item_code
